  ],
  "issues": [
    {
      "quote": "I start a new hobby recently, it is play guitar.",
      "type": "verb",
      "why": "時態與片語使用不正確；應使用完成式或現在完成進行，以及常用表達是\"take up\"或\"started playing the guitar\"。",
      "suggestion": "I started a new hobby recently: playing the guitar."
    },
    {
      "quote": "My father give me a old guitar",
      "type": "grammar",
      "why": "動詞沒有過去式，且冠詞使用錯誤（\"a old\" 應為 \"an old\"）。",
      "suggestion": "My father gave me an old guitar."
    },
    {
      "quote": "my finger is very pain",
      "type": "word-choice",
      "why": "\"pain\"是名詞，這裡需要形容詞或被動結構，如\"sore\"或\"in pain\"，語法不正確。",
      "suggestion": "my fingers are very sore"
    }
  ],
  "more": [
    {
      "quote": "it is play guitar",
      "type": "sentence",
      "why": "不符合英文習慣表達；動名詞或不定詞用法更自然。",
      "suggestion": "it is playing the guitar"
    },
    {
      "quote": "I watch YouTube to learn.",
      "type": "grammar",
      "why": "語法可接受但可更自然：通常說\"I watch YouTube videos\"或\"I learn on YouTube\"。",
